private List<ComponentMenuTreeDTO> filterMenuTreeByMenuGroup(
        List<ComponentMenuTreeDTO> tree, String menuGroup) {
    if (StringUtils.isBlank(menuGroup)) {
        return tree;                       // 不传就不过滤，兼容老调用方
    }
    List<ComponentMenuTreeDTO> result = new ArrayList<>();
    for (ComponentMenuTreeDTO node : tree) {
        // 叶子才判端：分组列只落在叶子菜单上
        if (CollectionUtils.isEmpty(node.getChildList())) {
            String group = StringUtils.defaultString(node.getMenuGroup(), MENU_GROUP_WEB);
            if (menuGroup.equals(group)) {
                result.add(node);
            }
            continue;
        }
        List<ComponentMenuTreeDTO> children = filterMenuTreeByMenuGroup(node.getChildList(), menuGroup);
        if (children.isEmpty()) {
            continue;                      // 子节点全被过滤掉，父节点不再单独出现
        }
        node.setChildList(children);
        result.add(node);
    }
    return result;
}

public List<ComponentMenuTreeDTO> queryComponentMenuList(String identification, String menuGroup) {
    List<ComponentMenu> menus = componentMenuDao.queryByComponentIdentification(identification);
    // r_component_menu 为空的是段下的一级分组菜单，非空的是子分组或功能菜单
    Map<Long, List<ComponentMenu>> childrenMap = menus.stream()
            .filter(m -> m.getR_component_menu() != null)
            .collect(Collectors.groupingBy(ComponentMenu::getR_component_menu));

    List<ComponentMenuTreeDTO> roots = new ArrayList<>();
    for (SegmentInfo segment : querySegmentList(identification)) {
        ComponentMenuTreeDTO segmentNode = new ComponentMenuTreeDTO();
        // 段的 id 用「段id + 下划线」：和菜单自增 id 永不冲突，又能被 parentId 引用
        segmentNode.setId(segment.getId() + "_");
        segmentNode.setParentId("#");
        segmentNode.setMenuName(segment.getName());
        segmentNode.setChildList(buildMenuNodes(segment.getId(), childrenMap));
        roots.add(segmentNode);
    }
    return filterMenuTreeByMenuGroup(roots, menuGroup);
}
